# ═══════════════ [F1M数据] 车队 ═══════════════
# ⚠ 以下全部是「虚构的占位测试数据」，只用来验证框架能否运行。
#   正式游玩前，请把它们替换成你自己的车队资料（或删除本条目，另建新条目）。
#
# 字段说明（除 id 外都可省略，省略时使用默认值）：
#   id              唯一标识（英文/数字），车手与赛历都用它引用车队
#   name / short    全称 / 三字母简称
#   color           车队主色（#RRGGBB），用于界面
#   principal       AI 车队的领队名字（玩家车队会被替换成玩家）
#   engine / base   动力单元供应商 / 车队基地（仅供叙事）
#   funds           初始资金（百万美元 M$）
#   sponsorIncome   每站赞助收入（M$）
#   operatingCost   每站运营成本（M$，计入预算帽）
#   targetPosition  董事会期望的车队排名
#   facilities      设施等级 1~5：windTunnel 风洞 / cfd CFD / simulator 模拟器 / factory 工厂
#   staff           关键员工：technicalDirector 技术总监 / aeroChief 空气动力学主管 /
#                   raceEngineer 比赛工程师 / pitCrew 维修组 / strategist 策略师
#                   每项可写 {name, skill(1~100), salary(年薪 M$)}，也可只写一个数字表示 skill
#   carBase         未单独填写的零件默认 {perf 性能, rel 可靠性}
#   parts           各零件初始 {perf, rel}，键为零件类型：
#                   power_unit 动力单元 / gearbox 变速箱 / chassis 底盘 / front_wing 前翼 /
#                   rear_wing 尾翼 / floor 底板 / sidepods 侧箱 / suspension 悬挂
#   description     车队简介（会显示在面板上）
teams:
  - id: team_a
    name: 测试车队A
    short: TSA
    color: '#e10600'
    principal: 占位领队A
    engine: 测试动力甲
    base: 测试基地A
    funds: 70
    sponsorIncome: 5
    operatingCost: 2.4
    targetPosition: 1
    facilities: { windTunnel: 4, cfd: 4, simulator: 4, factory: 4 }
    staff:
      technicalDirector: { name: 技术总监A, skill: 84, salary: 3 }
      aeroChief: { name: 空动主管A, skill: 80, salary: 2 }
      raceEngineer: { name: 工程师A, skill: 78, salary: 1 }
      pitCrew: { skill: 82, salary: 1.5 }
      strategist: { name: 策略师A, skill: 76, salary: 1 }
    carBase: { perf: 83, rel: 84 }
    parts:
      power_unit: { perf: 88, rel: 83 }
      floor: { perf: 84, rel: 85 }
    description: 占位数据：动力强劲的老牌强队，直道速度出众。

  - id: team_b
    name: 测试车队B
    short: TSB
    color: '#1e90ff'
    principal: 占位领队B
    engine: 测试动力乙
    base: 测试基地B
    funds: 65
    sponsorIncome: 4.6
    operatingCost: 2.3
    targetPosition: 2
    facilities: { windTunnel: 4, cfd: 3, simulator: 4, factory: 4 }
    staff:
      technicalDirector: { name: 技术总监B, skill: 80, salary: 2.6 }
      aeroChief: { name: 空动主管B, skill: 84, salary: 2.2 }
      raceEngineer: { name: 工程师B, skill: 80, salary: 1 }
      pitCrew: { skill: 86, salary: 1.5 }
      strategist: { name: 策略师B, skill: 80, salary: 1 }
    carBase: { perf: 81, rel: 88 }
    parts:
      floor: { perf: 86, rel: 88 }
      front_wing: { perf: 85, rel: 90 }
      power_unit: { perf: 80, rel: 90 }
    description: 占位数据：下压力出色、可靠性极高的稳健车队。

  - id: team_c
    name: 测试车队C
    short: TSC
    color: '#ff8700'
    principal: 占位领队C
    engine: 测试动力甲
    base: 测试基地C
    funds: 50
    sponsorIncome: 3.8
    operatingCost: 2
    targetPosition: 3
    facilities: { windTunnel: 3, cfd: 3, simulator: 3, factory: 3 }
    staff:
      technicalDirector: { name: 技术总监C, skill: 74, salary: 1.8 }
      aeroChief: { name: 空动主管C, skill: 72, salary: 1.4 }
      raceEngineer: { name: 工程师C, skill: 72, salary: 0.8 }
      pitCrew: { skill: 75, salary: 1 }
      strategist: { name: 策略师C, skill: 70, salary: 0.8 }
    carBase: { perf: 78, rel: 82 }
    parts:
      suspension: { perf: 82, rel: 84 }
      chassis: { perf: 80, rel: 84 }
    description: 占位数据：机械抓地扎实的中游车队，慢速弯表现好。

  - id: team_d
    name: 测试车队D
    short: TSD
    color: '#2fbf71'
    principal: 占位领队D
    engine: 测试动力乙
    base: 测试基地D
    funds: 40
    sponsorIncome: 3
    operatingCost: 1.8
    targetPosition: 4
    facilities: { windTunnel: 2, cfd: 3, simulator: 2, factory: 2 }
    staff:
      technicalDirector: { name: 技术总监D, skill: 68, salary: 1.2 }
      aeroChief: { name: 空动主管D, skill: 66, salary: 1 }
      raceEngineer: { name: 工程师D, skill: 68, salary: 0.6 }
      pitCrew: { skill: 70, salary: 0.8 }
      strategist: { name: 策略师D, skill: 66, salary: 0.6 }
    carBase: { perf: 74, rel: 78 }
    description: 占位数据：预算有限的尾部车队。

